fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since inputs have equal length and are non-empty, we can safely iterate with zip
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x ^ y)
     .collect()
}